<?php
/** Standalone publisher service contract tests; all Meta requests are mocked. Builder: Shashi. */
declare(strict_types=1);
require dirname(__DIR__).'/services/facebook-connect/src/Service.php';
use IDLM\Facebook\Service;
$passed=0;$failed=0;$now=2000000000;$calls=[];$rejectSubscription=false;
$database=sys_get_temp_dir().'/idlm-facebook-service-'.bin2hex(random_bytes(8)).'.sqlite';
$config=['app_id'=>'444','app_secret'=>'synthetic-app-secret','config_id'=>'445','verify_token'=>'synthetic-verify','base_url'=>'https://connect.example.test','database'=>$database,'encryption_key'=>random_bytes(32)];
$meta=static function($path,$query,$token,$method)use(&$calls,&$rejectSubscription){
    $calls[]=['path'=>$path,'query'=>$query,'token'=>$token,'method'=>$method];
    if($path==='oauth/access_token'){return ['access_token'=>isset($query['code'])?'user-token-'.$query['code']:$query['fb_exchange_token']];}
    if($path==='me'){return ['id'=>str_contains($token,'code-b')?'701':'700'];}
    if($path==='me/accounts'){return ['data'=>[['id'=>'111','name'=>'Business Alpha','access_token'=>'private-page-a'],['id'=>'112','name'=>'Business Beta','access_token'=>'private-page-b']]];}
    if($path==='111/leadgen_forms'){return ['data'=>[['id'=>'222','name'=>'Kitchen enquiries','status'=>'ACTIVE'],['id'=>'223','name'=>'Archived form','status'=>'ARCHIVED']]];}
    if($path==='112/leadgen_forms'){return ['data'=>[['id'=>'224','name'=>'Bedroom enquiries','status'=>'ACTIVE']]];}
    if($path==='222/leads'||$path==='224/leads'){return ['data'=>[['id'=>'999']],'paging'=>['next'=>'https://graph.facebook.com/?access_token=private-page-a','cursors'=>['after'=>'safe-cursor']]];}
    if(str_ends_with($path,'/subscribed_apps')){return $method==='POST'?['success'=>!$rejectSubscription]:['data'=>[['id'=>'444','subscribed_fields'=>['leadgen']]]];}
    if($path==='90001'){return ['id'=>'90001','form_id'=>'222','campaign_id'=>'987654321','campaign_name'=>'Synthetic campaign','unexpected'=>'private','field_data'=>[['name'=>'email','values'=>['synthetic@example.test']]]];}
    if($path==='90002'){return ['id'=>'90002','form_id'=>'224','field_data'=>[['name'=>'email','values'=>['other@example.test']]]];}
    throw new RuntimeException('Unexpected mocked Meta path '.$path);
};
$service=new Service($config,$meta,static function()use(&$now){return $now;});
function check($condition,string $message='Assertion failed'):void{if(!$condition){throw new RuntimeException($message);}}
function test(string $name,callable $test):void{global $passed,$failed;try{$test();$passed++;echo "PASS $name\n";}catch(Throwable $e){$failed++;echo "FAIL $name: {$e->getMessage()}\n";}}
function api(Service $service,array $site,string $action,array $data=[],?string $nonce=null,?string $signature=null):array{
    global $now;$raw=json_encode(['action'=>$action,'data'=>(object)$data],JSON_THROW_ON_ERROR);$nonce=$nonce??bin2hex(random_bytes(16));$headers=['X-IDLM-Site'=>$site['site_id'],'X-IDLM-Time'=>(string)$now,'X-IDLM-Nonce'=>$nonce,'X-IDLM-Signature'=>$signature??hash_hmac('sha256',$now."\n".$nonce."\n".$raw,$site['key'])];
    $response=$service->handle('POST','/api',$headers,[],$raw);
    if(isset($response['headers']['X-IDLM-Signature'])){check(hash_equals(hash_hmac('sha256',$nonce."\n".$response['status']."\n".$response['body'],$site['key']),$response['headers']['X-IDLM-Signature']),'Response is not authenticated');}
    $response['json']=json_decode($response['body'],true);return $response;
}
function authorize(Service $service,array $site,string $code):array{
    $pending=['session'=>bin2hex(random_bytes(16)),'claim'=>bin2hex(random_bytes(32)),'return_url'=>$site['origin'].'/workspace/?idlm_view=settings&idlm_fb_return=1'];
    $begin=api($service,$site,'begin',$pending);check($begin['status']===200,$begin['body']);parse_str(parse_url($begin['json']['authorization_url'],PHP_URL_QUERY),$q);check($q['config_id']==='445');
    $response=$service->handle('GET','/oauth/callback',[],['state'=>$q['state'],'code'=>$code],'');check($response['status']===303,$response['body']);check($response['headers']['Location']===$pending['return_url']);
    $pending['state']=$q['state'];return $pending;
}
$a=$service->provision('https://alpha.example.test');$a['origin']='https://alpha.example.test';$b=$service->provision('https://beta.example.test');$b['origin']='https://beta.example.test';
$pa=[];$pb=[];$ca=[];$cb=[];
test('service rejects unauthenticated and replayed installation requests',function()use($service,$a){check(api($service,$a,'status',[],null,str_repeat('0',64))['status']===401);$nonce=bin2hex(random_bytes(16));api($service,$a,'status',[],$nonce);check(api($service,$a,'status',[],$nonce)['status']===409);});
test('service restricts registered origins and return URLs',function()use($service,$a){$data=['session'=>bin2hex(random_bytes(16)),'claim'=>bin2hex(random_bytes(32)),'return_url'=>'https://attacker.example.test/'];check(api($service,$a,'begin',$data)['status']===400);foreach(['https://user@host.test','http://alpha.example.test',"https://alpha.example.test/\r\nLocation: evil"]as$url){check(!Service::https($url));}});
test('OAuth exchanges code server-side and returns only to registered installation',function()use($service,$a,&$pa,&$calls){$pa=authorize($service,$a,'code-a');$exchange=array_values(array_filter($calls,static fn($call)=>$call['path']==='oauth/access_token'))[0];check($exchange['method']==='POST');check($exchange['query']['client_secret']==='synthetic-app-secret');check($service->handle('GET','/oauth/callback',[],['state'=>$pa['state'],'code'=>'code-a'],'')['status']===403);});
test('Pages expose names without access tokens and sessions are tenant-bound',function()use($service,$a,$b,&$pa){$r=api($service,$a,'pages',$pa);check($r['status']===200);check($r['json']['pages'][0]['name']==='Business Alpha');check(!str_contains($r['body'],'private-page'));check(api($service,$b,'pages',$pa)['status']===403);});
test('Forms are scoped to a granted Page and include only active individual forms',function()use($service,$a,&$pa){check(api($service,$a,'forms',$pa+['page_id'=>'999'])['status']===403);$r=api($service,$a,'forms',$pa+['page_id'=>'111']);check($r['json']['forms']===[['id'=>'222','name'=>'Kitchen enquiries']]);});
test('Selection rejects undiscovered forms and requires confirmed subscription',function()use($service,$a,&$pa,&$rejectSubscription){check(api($service,$a,'select',$pa+['page_id'=>'111','forms'=>['224']])['status']===403);$rejectSubscription=true;check(api($service,$a,'select',$pa+['page_id'=>'111','forms'=>['222']])['status']===502);$rejectSubscription=false;});
test('Successful selection is idempotent after a lost response',function()use($service,$a,&$pa,&$ca){$r=api($service,$a,'select',$pa+['page_id'=>'111','forms'=>['222']]);check($r['status']===200,$r['body']);$ca=$r['json'];$again=api($service,$a,'select',$pa+['page_id'=>'111','forms'=>['222']]);check($again['json']===$ca);check(!str_contains($r['body'],'private-page'));});
test('Another customer cannot take an already-connected Page',function()use($service,$b,&$pb,&$cb){$pb=authorize($service,$b,'code-b');api($service,$b,'pages',$pb);api($service,$b,'forms',$pb+['page_id'=>'111']);check(api($service,$b,'select',$pb+['page_id'=>'111','forms'=>['222']])['status']===409);api($service,$b,'forms',$pb+['page_id'=>'112']);$r=api($service,$b,'select',$pb+['page_id'=>'112','forms'=>['224']]);check($r['status']===200);$cb=$r['json'];});
test('Webhook requires signature and verification challenge is plain text',function()use($service){check($service->handle('POST','/meta/webhook',[],[],'{}')['status']===401);$r=$service->handle('GET','/meta/webhook',[],['hub_mode'=>'subscribe','hub_verify_token'=>'synthetic-verify','hub_challenge'=>'0'],'');check($r['status']===200&&$r['body']==='0');});
test('Signed events queue only selected forms and stay isolated by installation',function()use($service,$config,$a,$b,&$ca,&$cb){$data=['object'=>'page','entry'=>[['id'=>'111','changes'=>[['field'=>'leadgen','value'=>['page_id'=>'111','form_id'=>'222','leadgen_id'=>'90001']],['field'=>'leadgen','value'=>['page_id'=>'111','form_id'=>'999','leadgen_id'=>'90002']]]]]];$body=json_encode($data);$headers=['X-Hub-Signature-256'=>'sha256='.hash_hmac('sha256',$body,$config['app_secret'])];check($service->handle('POST','/meta/webhook',$headers,[],$body)['status']===200);$service->handle('POST','/meta/webhook',$headers,[],$body);$ra=api($service,$a,'events',['connection'=>$ca['connection']]);check(count($ra['json']['events'])===1);check(api($service,$b,'events',['connection'=>$cb['connection']])['json']['events']===[]);$id=(int)$ra['json']['events'][0]['id'];api($service,$b,'ack',['connection'=>$cb['connection'],'ids'=>[$id]]);check(count(api($service,$a,'events',['connection'=>$ca['connection']])['json']['events'])===1);});
test('Lead retrieval proxy rejects other forms and unrestricted API paths',function()use($service,$a,&$ca){$base=['connection'=>$ca['connection']];check(api($service,$a,'graph',$base+['path'=>'me/accounts','query'=>[]])['status']===403);$q=['fields'=>'id,created_time,form_id,ad_id,field_data'];check(api($service,$a,'graph',$base+['path'=>'90002','query'=>$q])['status']===403);$r=api($service,$a,'graph',$base+['path'=>'90001','query'=>$q]);check($r['json']['id']==='90001');check(api($service,$a,'graph',['connection'=>str_repeat('0',32),'path'=>'90001','query'=>$q])['status']===409);});
test('Lead enrichment remains scoped to selected forms and requested fields',function()use($service,$a,&$ca){$base=['connection'=>$ca['connection']];$fields='id,created_time,form_id,ad_id,field_data,ad_name,adset_id,adset_name,campaign_id,campaign_name,is_organic,platform,partner_name';$q=['fields'=>$fields];$r=api($service,$a,'graph',$base+['path'=>'90001','query'=>$q]);check($r['json']['campaign_id']==='987654321');check(!isset($r['json']['unexpected']));check(api($service,$a,'graph',$base+['path'=>'90002','query'=>$q])['status']===403);$full=$fields.',custom_disclaimer_responses,home_listing,post,post_submission_check_result,retailer_item_id,vehicle';check(api($service,$a,'graph',$base+['path'=>'90001','query'=>['fields'=>$full]])['status']===200);check(api($service,$a,'graph',$base+['path'=>'90001','query'=>['fields'=>$fields.',access_token']])['status']===403);});
test('Lead-list pagination never exposes Meta token-bearing next URLs',function()use($service,$a,&$ca){$r=api($service,$a,'graph',['connection'=>$ca['connection'],'path'=>'222/leads','query'=>['fields'=>'id','limit'=>25]]);check($r['status']===200);check(!str_contains($r['body'],'private-page'));check($r['json']['paging']['next']===true);check($r['json']['paging']['cursors']['after']==='safe-cursor');});
test('Private tokens and credentials are encrypted at rest',function()use($database){$bytes=file_get_contents($database).(is_file($database.'-wal')?file_get_contents($database.'-wal'):'');foreach(['private-page-a','private-page-b','user-token-code-a','synthetic-app-secret']as$secret){check(!str_contains($bytes,$secret),'Plaintext stored: '.$secret);}});
test('Signed data-deletion request removes the correct user only',function()use($service,$a,$b,$config,&$ca,&$cb){$payload=rtrim(strtr(base64_encode(json_encode(['algorithm'=>'HMAC-SHA256','user_id'=>'700'])),'+/','-_'),'=');$signature=rtrim(strtr(base64_encode(hash_hmac('sha256',$payload,$config['app_secret'],true)),'+/','-_'),'=');$body=http_build_query(['signed_request'=>$signature.'.'.$payload]);$r=$service->handle('POST','/meta/delete-data',[],[],$body);check($r['status']===200);check(api($service,$a,'events',['connection'=>$ca['connection']])['status']===409);check(api($service,$b,'status')['status']===200);});
