    $other=new Service($otherConfig,$transport,static function()use(&$now){return $now;});$tenant=$other->provision('https://race.example.test');$tenant['origin']='https://race.example.test';$pending=authorize($other,$tenant,'code-a');api($other,$tenant,'pages',$pending);api($other,$tenant,'forms',$pending+['page_id'=>'111']);$r=api($other,$tenant,'select',$pending+['page_id'=>'111','forms'=>['222']]);check($r['status']===409);check(api($other,$tenant,'status')['status']===409);unset($other);foreach([$otherConfig['database'],$otherConfig['database'].'-wal',$otherConfig['database'].'-shm']as$file){if(is_file($file)){unlink($file);}}
});
